<?php $pageTitle='Vendas'; require_once __DIR__.'/../../includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$cliente=(int)($_POST['cliente_id']??0)?:null;$produto=(int)$_POST['produto_id'];$qtd=(float)$_POST['quantidade'];$forma=$_POST['forma_pagamento'];$st=$pdo->prepare('SELECT * FROM produtos WHERE id=?');$st->execute([$produto]);$p=$st->fetch();if(!$p||$p['estoque_atual']<$qtd){flash('err','Estoque insuficiente.');header('Location:index.php');exit;}$total=$qtd*$p['preco_venda'];$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO vendas(cliente_id,usuario_id,total,status,forma_pagamento) VALUES(?,?,?,?,?)')->execute([$cliente,$_SESSION['user']['id'],$total,'CONCLUIDA',$forma]);$venda=$pdo->lastInsertId();$pdo->prepare('INSERT INTO venda_itens(venda_id,produto_id,quantidade,preco_unitario,subtotal) VALUES(?,?,?,?,?)')->execute([$venda,$produto,$qtd,$p['preco_venda'],$total]);$pdo->prepare('UPDATE produtos SET estoque_atual=estoque_atual-? WHERE id=?')->execute([$qtd,$produto]);$pdo->prepare('INSERT INTO movimentacoes_estoque(produto_id,tipo,quantidade,observacao,usuario_id) VALUES(?,?,?,?,?)')->execute([$produto,'SAIDA',$qtd,'Venda #'.$venda,$_SESSION['user']['id']]);$pdo->prepare('INSERT INTO financeiro(tipo,descricao,valor,vencimento,status,categoria) VALUES("RECEITA",?,?,CURDATE(),"PAGO","VENDAS")')->execute(['Venda #'.$venda,$total]);$pdo->commit();flash('ok','Venda #'.$venda.' concluída.');}catch(Throwable $e){$pdo->rollBack();flash('err',$e->getMessage());}header('Location:index.php');exit;}
$clientes=$pdo->query('SELECT id,nome FROM clientes WHERE status="ATIVO" ORDER BY nome')->fetchAll();$produtos=$pdo->query('SELECT id,sku,nome,preco_venda,estoque_atual FROM produtos WHERE status="ATIVO" ORDER BY nome')->fetchAll();$rows=$pdo->query('SELECT v.*,c.nome cliente,u.nome vendedor FROM vendas v LEFT JOIN clientes c ON c.id=v.cliente_id LEFT JOIN usuarios u ON u.id=v.usuario_id ORDER BY v.id DESC')->fetchAll(); ?>
<div class="panel mb-3"><div class="panel-title"><h3>Registrar venda</h3></div><form method="post" class="row g-3"><div class="col-md-3"><label>Cliente</label><select name="cliente_id" class="form-select"><option value="">Consumidor final</option><?php foreach($clientes as $c):?><option value="<?=$c['id']?>"><?=e($c['nome'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label>Produto</label><select name="produto_id" class="form-select" required><?php foreach($produtos as $p):?><option value="<?=$p['id']?>"><?=e($p['sku'].' - '.$p['nome'])?> · <?=money($p['preco_venda'])?> · est. <?=e($p['estoque_atual'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Quantidade</label><input name="quantidade" type="number" step="0.01" min="0.01" class="form-control" required></div><div class="col-md-3"><label>Pagamento</label><select name="forma_pagamento" class="form-select"><option>PIX</option><option>CARTAO</option><option>DINHEIRO</option><option>BOLETO</option></select></div><div class="col-12"><button class="btn btn-dark">Concluir venda</button></div></form></div>
<div class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>#</th><th>Data</th><th>Cliente</th><th>Vendedor</th><th>Pagamento</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=date('d/m/Y H:i',strtotime($r['data_venda']))?></td><td><?=e($r['cliente']??'Consumidor final')?></td><td><?=e($r['vendedor']??'-')?></td><td><?=e($r['forma_pagamento'])?></td><td><?=e($r['status'])?></td><td><?=money($r['total'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>